import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;
    static final long LIM = Long.MAX_VALUE - MOD * MOD;

    static class Matrix {
        int size;
        int[][] mat;

        Matrix(int size) {
            this.size = size;
            this.mat = new int[size + 1][size + 1];
        }

        Matrix copy() {
            Matrix copy = new Matrix(this.size);
            for (int i = 0; i <= size; i++) {
                System.arraycopy(this.mat[i], 0, copy.mat[i], 0, size + 1);
            }
            return copy;
        }
    }

    static int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    static void matrixMultiply(Matrix A, Matrix B, Matrix C, int size) {
        for (int i = 0; i <= size; i++) {
            for (int j = 0; j <= size; j++) {
                long sum = 0;
                for (int k = 0; k <= size; k++) {
                    if (sum > LIM) sum %= MOD;
                    sum += (long) A.mat[i][k] * B.mat[k][j];
                }
                C.mat[i][j] = (int) (sum % MOD);
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int base = sc.nextInt();

        int size = base;
        Matrix[][][] mat = new Matrix[60][size][];
        for (int i = 0; i < 60; i++) {
            for (int j = 0; j < size; j++) {
                mat[i][j] = new Matrix[size];
                for (int k = 0; k < size; k++) {
                    mat[i][j][k] = new Matrix(size);
                }
            }
        }

        // Initialize mat[0][i]
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                for (int k = 0; k <= size; k++) {
                    mat[0][i][j].mat[k][k] = (i == j || j == k) ? 1 : 0;
                }
            }
        }

        int ci = 0, cj = 0;
        long step = 1;
        while (step <= n / size) {
            ci++;
            step *= size;
        }

        // Build higher matrices
        for (int i = 1; i <= ci; i++) {
            for (int j = 0; j < size; j++) {
                // Initialize mat[i][j]
                for (int k = 0; k < size; k++) {
                    for (int l = 0; l <= size; l++) {
                        mat[i][j][k].mat[l][l] = (k == l) ? 1 : 0;
                    }
                }
                for (int k = 0; k < size; k++) {
                    Matrix tmp = new Matrix(size);
                    matrixMultiply(mat[i][j], mat[i - 1][(j + k) % size], tmp, size);
                    mat[i][j] = tmp;
                }
            }
        }

        // Initialize 'have' matrix
        Matrix have = new Matrix(size);
        for (int k = 0; k <= size; k++) {
            for (int l = 0; l <= size; l++) {
                have.mat[k][l] = (k == l) ? 1 : 0;
            }
        }

        // Decompose n
        for (; ci >= 0; ci--, step /= size) {
            int times = (int) ((n / step) % size);
            for (int x = 0; x < times; x++) {
                Matrix tmp = new Matrix(size);
                matrixMultiply(have, mat[ci][cj], tmp, size);
                have = tmp;
                cj++;
                if (cj >= size) cj -= size;
            }
        }

        long result = 0;
        for (int k = 0; k <= size; k++) {
            result += have.mat[k][size];
            if (result >= MOD) result -= MOD;
        }
        System.out.println(result);
        sc.close();
    }
}
